/**
 * The processor language, as the game defines it.
 *
 * Nothing here is typed by hand. `instructions.json` is generated by
 * `tools/build_logic_catalogue.py`, which disassembles `mindustry.gen.LogicIO.write` to
 * learn the name and the operands of every instruction, opens the enum classes those
 * operands point at, and takes the help text out of the game's own translation bundles.
 *
 * A hand-kept instruction table does not break, it drifts: an instruction appears in a
 * build, nobody notices, and working programs get painted red for a year.
 *
 * Loaded the same way `analyse.js` loads its block registry, and for the same reason: the
 * page fetches one JSON, the tests read the same file off disk, and there is only ever one
 * copy of the truth.
 */

let catalogue = null;

/** Install a catalogue already in hand. What the tests use. */
export function useCatalogue(data) {
  const byName = new Map(data.instructions.map((entry) => [entry.name, entry]));

  /* The values of every fixed list, flattened once. Answering "is `angle` a `LogicOp`" by
     scanning an array of objects on every keystroke is how an editor comes to stutter. */
  const enums = new Map();
  for (const [name, values] of Object.entries(data.enums)) {
    enums.set(name, {
      values,
      has: new Set(values.map((value) => value.name)),
    });
  }

  const content = new Set();
  for (const names of Object.values(data.content)) {
    for (const name of names) content.add(`@${name}`);
  }

  catalogue = { ...data, byName, enums, content };
  return catalogue;
}

/** Fetch the catalogue the page ships with. */
export async function loadCatalogue() {
  if (catalogue) return catalogue;
  /* Resolved against this module rather than against the page: this tool is served at
     `/outils/logique` and the file sits next to the code that reads it. */
  const answer = await fetch(new URL("./instructions.json", import.meta.url));
  if (!answer.ok) throw new Error(`catalogue illisible (${answer.status})`);
  return useCatalogue(await answer.json());
}

/** The catalogue in use, once one is. */
export function catalogueOf() {
  if (!catalogue) throw new Error("catalogue pas encore charge");
  return catalogue;
}

/**
 * The spelling the game will actually use.
 *
 * `LParser` rewrites `atan2` to `angle`, `dst` to `len` and both spellings of `configure`
 * to `config`, silently, so that programs written before those renames keep working. An
 * editor that does not do the same underlines correct code.
 */
export function resolved(token) {
  return catalogueOf().aliases[token] ?? token;
}

/** One instruction, or nothing at all. */
export function instruction(name) {
  return catalogueOf().byName.get(resolved(name)) ?? null;
}

/** Whether `value` belongs to the fixed list named by an operand. */
export function inEnum(list, value) {
  return catalogueOf().enums.get(list)?.has.has(resolved(value)) ?? false;
}

/** The values of one fixed list, in the order the game declares them. */
export function valuesOf(list) {
  return catalogueOf().enums.get(list)?.values ?? [];
}

/** Whether `@copper` and friends name something the game ships. */
export function isContent(token) {
  return catalogueOf().content.has(token);
}

/**
 * What may follow, at operand `at` of `name`.
 *
 * The catalogue knows an operand is a `LAccess` or a free value, and that answers most of
 * it. What it cannot know is that the third operand of `sensor` is a free string in the
 * game's own model and yet only ever holds a property name or a content name. That last
 * mile is here, it is short, and it steers suggestions without ever deciding what is
 * valid: a program is never marked wrong on the strength of this table.
 */
const SUGGESTS = {
  "sensor.2": ["LAccess", "content"],
  "lookup.1": [],
  "control.1": ["links"],
  "read.1": ["links"],
  "write.1": ["links"],
  "printflush.0": ["links"],
  "drawflush.0": ["links"],
  "getlink.1": [],
  "radar.4": ["links"],
  "ulocate.3": ["content"],
};

/** The suggestion sources for one operand, beyond the operand's own type. */
export function suggestsFor(name, at) {
  return SUGGESTS[`${resolved(name)}.${at}`] ?? [];
}
